//! Generated by `flui_driver::trace::codegen` from a trace of counter: edit freely.

use flui_driver::{Driver, Launch, Locator, TextMatch, expect};

#[test]
fn a_generated_test_taps_the_counter() -> flui_driver::Result<()> {
    let mut driver = Driver::launch(Launch::headless(|| crate::fixtures::Counter { probe: crate::fixtures::Probe::default() }))?;
    driver.main_window()?.locate(Locator::named("Increment")).tap()?;
    expect(driver.main_window()?.locate(Locator::default().name_matching(TextMatch::prefix("Count:")))).timeout(std::time::Duration::from_millis(5000)).to_have_name("Count: 1")?;
    Ok(())
}
